insert into public.monthly_ai_catalog(exam_id,version,content) values ('primary-step2','2026-10-16-v1', '{"id":"primary-step2","version":"2026-10-16-v1","title":"TOEFL Primary Step 2 Monthly Examination","sections":[{"id":"reading","title":"Reading"},{"id":"vocabulary","title":"Vocabulary"},{"id":"language","title":"Language Form and Meaning"},{"id":"writing","title":"Writing"},{"id":"speaking","title":"Speaking"}],"objective":[{"id":"reading","title":"Reading","questions":[{"id":"r0","text":"What is Anna''s book about?","options":["Cars","Birds","Flowers","Boats"],"key":1,"explanation":"The story says Anna brought \"a book about birds\" to school.","passage":"A Book for the ClassOn Monday, Anna brought a book about birds to school. Her grandfather had given it to her for her birthday. At lunchtime, she showed it to her friend Tom in the library. Tom liked the pictures, but he could not read some of the long words. Anna helped him. Then their teacher, Miss Green, asked Anna to show the book to the class on Friday. Anna felt nervous because she had never spoken in front of everyone before. Tom offered to hold the book while she talked. They practised together after school. On Friday, Anna told the class about three birds. Everyone listened carefully, and Anna smiled."},{"id":"r1","text":"Who gave Anna the book?","options":["Her grandfather","Tom","Miss Green","Her sister"],"key":0,"explanation":"The story says \"Her grandfather had given it to her.\"","passage":"A Book for the ClassOn Monday, Anna brought a book about birds to school. Her grandfather had given it to her for her birthday. At lunchtime, she showed it to her friend Tom in the library. Tom liked the pictures, but he could not read some of the long words. Anna helped him. Then their teacher, Miss Green, asked Anna to show the book to the class on Friday. Anna felt nervous because she had never spoken in front of everyone before. Tom offered to hold the book while she talked. They practised together after school. On Friday, Anna told the class about three birds. Everyone listened carefully, and Anna smiled."},{"id":"r2","text":"Why did Anna receive the book?","options":["She won a race.","She lost her old book.","She finished her homework.","It was her birthday."],"key":3,"explanation":"He gave it to her \"for her birthday\".","passage":"A Book for the ClassOn Monday, Anna brought a book about birds to school. Her grandfather had given it to her for her birthday. At lunchtime, she showed it to her friend Tom in the library. Tom liked the pictures, but he could not read some of the long words. Anna helped him. Then their teacher, Miss Green, asked Anna to show the book to the class on Friday. Anna felt nervous because she had never spoken in front of everyone before. Tom offered to hold the book while she talked. They practised together after school. On Friday, Anna told the class about three birds. Everyone listened carefully, and Anna smiled."},{"id":"r3","text":"Where did Anna show Tom the book?","options":["In the garden","At the bus stop","In the library","In the playground"],"key":2,"explanation":"She showed it to Tom \"at lunchtime ... in the library\".","passage":"A Book for the ClassOn Monday, Anna brought a book about birds to school. Her grandfather had given it to her for her birthday. At lunchtime, she showed it to her friend Tom in the library. Tom liked the pictures, but he could not read some of the long words. Anna helped him. Then their teacher, Miss Green, asked Anna to show the book to the class on Friday. Anna felt nervous because she had never spoken in front of everyone before. Tom offered to hold the book while she talked. They practised together after school. On Friday, Anna told the class about three birds. Everyone listened carefully, and Anna smiled."},{"id":"r4","text":"What did Tom find difficult?","options":["Looking at the pictures","Reading some long words","Finding the library","Holding the book"],"key":1,"explanation":"Tom \"could not read some of the long words\"; he liked the pictures.","passage":"A Book for the ClassOn Monday, Anna brought a book about birds to school. Her grandfather had given it to her for her birthday. At lunchtime, she showed it to her friend Tom in the library. Tom liked the pictures, but he could not read some of the long words. Anna helped him. Then their teacher, Miss Green, asked Anna to show the book to the class on Friday. Anna felt nervous because she had never spoken in front of everyone before. Tom offered to hold the book while she talked. They practised together after school. On Friday, Anna told the class about three birds. Everyone listened carefully, and Anna smiled."},{"id":"r5","text":"When did Anna speak to the class?","options":["On Friday","On Monday","On Tuesday","On Sunday"],"key":0,"explanation":"Miss Green asked her to show the book to the class \"on Friday\", and on Friday she spoke.","passage":"A Book for the ClassOn Monday, Anna brought a book about birds to school. Her grandfather had given it to her for her birthday. At lunchtime, she showed it to her friend Tom in the library. Tom liked the pictures, but he could not read some of the long words. Anna helped him. Then their teacher, Miss Green, asked Anna to show the book to the class on Friday. Anna felt nervous because she had never spoken in front of everyone before. Tom offered to hold the book while she talked. They practised together after school. On Friday, Anna told the class about three birds. Everyone listened carefully, and Anna smiled."},{"id":"r6","text":"Why did Anna feel nervous?","options":["She could not find her book.","She was late for school.","She did not like birds.","She had not spoken in front of the class before."],"key":3,"explanation":"She felt nervous \"because she had never spoken in front of everyone before\".","passage":"A Book for the ClassOn Monday, Anna brought a book about birds to school. Her grandfather had given it to her for her birthday. At lunchtime, she showed it to her friend Tom in the library. Tom liked the pictures, but he could not read some of the long words. Anna helped him. Then their teacher, Miss Green, asked Anna to show the book to the class on Friday. Anna felt nervous because she had never spoken in front of everyone before. Tom offered to hold the book while she talked. They practised together after school. On Friday, Anna told the class about three birds. Everyone listened carefully, and Anna smiled."},{"id":"r7","text":"How did Tom offer to help Anna?","options":["By buying a new book","By drawing all the birds","By holding the book while she talked","By speaking instead of her"],"key":2,"explanation":"\"Tom offered to hold the book while she talked.\"","passage":"A Book for the ClassOn Monday, Anna brought a book about birds to school. Her grandfather had given it to her for her birthday. At lunchtime, she showed it to her friend Tom in the library. Tom liked the pictures, but he could not read some of the long words. Anna helped him. Then their teacher, Miss Green, asked Anna to show the book to the class on Friday. Anna felt nervous because she had never spoken in front of everyone before. Tom offered to hold the book while she talked. They practised together after school. On Friday, Anna told the class about three birds. Everyone listened carefully, and Anna smiled."},{"id":"r8","text":"What did Anna and Tom do after school?","options":["They visited her grandfather.","They practised together.","They watched a film.","They bought a present."],"key":1,"explanation":"The story says \"They practised together after school.\"","passage":"A Book for the ClassOn Monday, Anna brought a book about birds to school. Her grandfather had given it to her for her birthday. At lunchtime, she showed it to her friend Tom in the library. Tom liked the pictures, but he could not read some of the long words. Anna helped him. Then their teacher, Miss Green, asked Anna to show the book to the class on Friday. Anna felt nervous because she had never spoken in front of everyone before. Tom offered to hold the book while she talked. They practised together after school. On Friday, Anna told the class about three birds. Everyone listened carefully, and Anna smiled."},{"id":"r9","text":"What is the story mainly about?","options":["A friend helps a girl share her book with the class.","A teacher buys a birthday present.","Two children find a lost bird.","A boy learns to paint a picture."],"key":0,"explanation":"The whole story is about Tom helping Anna share her bird book with the class.","passage":"A Book for the ClassOn Monday, Anna brought a book about birds to school. Her grandfather had given it to her for her birthday. At lunchtime, she showed it to her friend Tom in the library. Tom liked the pictures, but he could not read some of the long words. Anna helped him. Then their teacher, Miss Green, asked Anna to show the book to the class on Friday. Anna felt nervous because she had never spoken in front of everyone before. Tom offered to hold the book while she talked. They practised together after school. On Friday, Anna told the class about three birds. Everyone listened carefully, and Anna smiled."},{"id":"r10","text":"When did the family plan their picnic?","options":["On Friday evening","On Sunday afternoon","On Monday morning","On Saturday morning"],"key":3,"explanation":"The story begins \"On Saturday morning, Jack and his family planned a picnic\".","passage":"The Rainy PicnicOn Saturday morning, Jack and his family planned a picnic by the lake. Dad packed sandwiches, and Jack put apples in a bag. His little sister Emma brought a red ball. When they reached the lake, dark clouds covered the sky. Soon it began to rain. Mum saw a small shelter near the trees, so the family went inside. They ate their food there and watched ducks swimming on the lake. Emma was disappointed because she wanted to play with her ball. Jack made up a guessing game to cheer her up. After lunch, the rain stopped. The children played on the grass while Dad took photos. Before going home, everyone picked up their rubbish."},{"id":"r11","text":"Where did they plan to have the picnic?","options":["At school","In a shop","By the lake","At the beach"],"key":2,"explanation":"They planned \"a picnic by the lake\".","passage":"The Rainy PicnicOn Saturday morning, Jack and his family planned a picnic by the lake. Dad packed sandwiches, and Jack put apples in a bag. His little sister Emma brought a red ball. When they reached the lake, dark clouds covered the sky. Soon it began to rain. Mum saw a small shelter near the trees, so the family went inside. They ate their food there and watched ducks swimming on the lake. Emma was disappointed because she wanted to play with her ball. Jack made up a guessing game to cheer her up. After lunch, the rain stopped. The children played on the grass while Dad took photos. Before going home, everyone picked up their rubbish."},{"id":"r12","text":"What food did Dad pack?","options":["Rice","Sandwiches","Biscuits","Bananas"],"key":1,"explanation":"The story says \"Dad packed sandwiches\".","passage":"The Rainy PicnicOn Saturday morning, Jack and his family planned a picnic by the lake. Dad packed sandwiches, and Jack put apples in a bag. His little sister Emma brought a red ball. When they reached the lake, dark clouds covered the sky. Soon it began to rain. Mum saw a small shelter near the trees, so the family went inside. They ate their food there and watched ducks swimming on the lake. Emma was disappointed because she wanted to play with her ball. Jack made up a guessing game to cheer her up. After lunch, the rain stopped. The children played on the grass while Dad took photos. Before going home, everyone picked up their rubbish."},{"id":"r13","text":"What did Emma bring?","options":["A red ball","A blue kite","A yellow bag","A green book"],"key":0,"explanation":"\"His little sister Emma brought a red ball.\"","passage":"The Rainy PicnicOn Saturday morning, Jack and his family planned a picnic by the lake. Dad packed sandwiches, and Jack put apples in a bag. His little sister Emma brought a red ball. When they reached the lake, dark clouds covered the sky. Soon it began to rain. Mum saw a small shelter near the trees, so the family went inside. They ate their food there and watched ducks swimming on the lake. Emma was disappointed because she wanted to play with her ball. Jack made up a guessing game to cheer her up. After lunch, the rain stopped. The children played on the grass while Dad took photos. Before going home, everyone picked up their rubbish."},{"id":"r14","text":"Why did the family go into the shelter?","options":["They wanted to sleep.","They were looking for a shop.","It was too sunny.","It began to rain."],"key":3,"explanation":"They went inside because \"soon it began to rain\".","passage":"The Rainy PicnicOn Saturday morning, Jack and his family planned a picnic by the lake. Dad packed sandwiches, and Jack put apples in a bag. His little sister Emma brought a red ball. When they reached the lake, dark clouds covered the sky. Soon it began to rain. Mum saw a small shelter near the trees, so the family went inside. They ate their food there and watched ducks swimming on the lake. Emma was disappointed because she wanted to play with her ball. Jack made up a guessing game to cheer her up. After lunch, the rain stopped. The children played on the grass while Dad took photos. Before going home, everyone picked up their rubbish."},{"id":"r15","text":"What did the family watch while eating?","options":["Children dancing","Dogs running","Ducks swimming","Boats racing"],"key":2,"explanation":"They \"watched ducks swimming on the lake\" while they ate.","passage":"The Rainy PicnicOn Saturday morning, Jack and his family planned a picnic by the lake. Dad packed sandwiches, and Jack put apples in a bag. His little sister Emma brought a red ball. When they reached the lake, dark clouds covered the sky. Soon it began to rain. Mum saw a small shelter near the trees, so the family went inside. They ate their food there and watched ducks swimming on the lake. Emma was disappointed because she wanted to play with her ball. Jack made up a guessing game to cheer her up. After lunch, the rain stopped. The children played on the grass while Dad took photos. Before going home, everyone picked up their rubbish."},{"id":"r16","text":"In the story, what does disappointed mean?","options":["Excited about a surprise","Sad because something you wanted did not happen","Too tired to stay awake","Unable to hear a sound"],"key":1,"explanation":"Emma was disappointed because she wanted to play with her ball and could not: sad because something you wanted did not happen.","passage":"The Rainy PicnicOn Saturday morning, Jack and his family planned a picnic by the lake. Dad packed sandwiches, and Jack put apples in a bag. His little sister Emma brought a red ball. When they reached the lake, dark clouds covered the sky. Soon it began to rain. Mum saw a small shelter near the trees, so the family went inside. They ate their food there and watched ducks swimming on the lake. Emma was disappointed because she wanted to play with her ball. Jack made up a guessing game to cheer her up. After lunch, the rain stopped. The children played on the grass while Dad took photos. Before going home, everyone picked up their rubbish."},{"id":"r17","text":"How did Jack cheer Emma up?","options":["He made up a guessing game.","He bought another ball.","He took her home.","He gave her a camera."],"key":0,"explanation":"\"Jack made up a guessing game to cheer her up.\"","passage":"The Rainy PicnicOn Saturday morning, Jack and his family planned a picnic by the lake. Dad packed sandwiches, and Jack put apples in a bag. His little sister Emma brought a red ball. When they reached the lake, dark clouds covered the sky. Soon it began to rain. Mum saw a small shelter near the trees, so the family went inside. They ate their food there and watched ducks swimming on the lake. Emma was disappointed because she wanted to play with her ball. Jack made up a guessing game to cheer her up. After lunch, the rain stopped. The children played on the grass while Dad took photos. Before going home, everyone picked up their rubbish."},{"id":"r18","text":"What happened after lunch?","options":["The family arrived at the lake.","Dad packed sandwiches.","Emma put apples in a bag.","The rain stopped."],"key":3,"explanation":"The story says \"After lunch, the rain stopped.\"","passage":"The Rainy PicnicOn Saturday morning, Jack and his family planned a picnic by the lake. Dad packed sandwiches, and Jack put apples in a bag. His little sister Emma brought a red ball. When they reached the lake, dark clouds covered the sky. Soon it began to rain. Mum saw a small shelter near the trees, so the family went inside. They ate their food there and watched ducks swimming on the lake. Emma was disappointed because she wanted to play with her ball. Jack made up a guessing game to cheer her up. After lunch, the rain stopped. The children played on the grass while Dad took photos. Before going home, everyone picked up their rubbish."},{"id":"r19","text":"What did everyone do before going home?","options":["They went swimming.","They fed the ducks sandwiches.","They picked up their rubbish.","They planted a tree."],"key":2,"explanation":"\"Before going home, everyone picked up their rubbish.\"","passage":"The Rainy PicnicOn Saturday morning, Jack and his family planned a picnic by the lake. Dad packed sandwiches, and Jack put apples in a bag. His little sister Emma brought a red ball. When they reached the lake, dark clouds covered the sky. Soon it began to rain. Mum saw a small shelter near the trees, so the family went inside. They ate their food there and watched ducks swimming on the lake. Emma was disappointed because she wanted to play with her ball. Jack made up a guessing game to cheer her up. After lunch, the rain stopped. The children played on the grass while Dad took photos. Before going home, everyone picked up their rubbish."}]},{"id":"vocabulary","title":"Vocabulary","questions":[{"id":"v0","text":"My <u>neighbour</u> lives next door.<p>What does the underlined word or phrase mean?</p>","options":["a person who teaches your class","a person who lives near you","a person who sells food","a person who drives a bus"],"key":1,"explanation":"In this sentence, the underlined word means \"a person who lives near you\". The other options do not fit the sentence."},{"id":"v1","text":"Our <u>neighbourhood</u> has a park and many homes.<p>What does the underlined word or phrase mean?</p>","options":["the area around the place where you live","a room where you eat","a long journey on a boat","a person who helps you"],"key":0,"explanation":"In this sentence, the underlined word means \"the area around the place where you live\". The other options do not fit the sentence."},{"id":"v2","text":"That new playground is <u>awesome</u>!<p>What does the underlined word or phrase mean?</p>","options":["very small and hard to see","very old and broken","very quiet and empty","very good or exciting"],"key":3,"explanation":"In this sentence, the underlined word means \"very good or exciting\". The other options do not fit the sentence."},{"id":"v3","text":"Many kinds of fish live in the <u>ocean</u>.<p>What does the underlined word or phrase mean?</p>","options":["a small bowl of clean water","a high place made of rocks","a very large area of salt water","a dry place with no plants"],"key":2,"explanation":"In this sentence, the underlined word means \"a very large area of salt water\". The other options do not fit the sentence."},{"id":"v4","text":"We <u>breathe</u> air through our noses and mouths.<p>What does the underlined word or phrase mean?</p>","options":["to drink a glass of water","to take air into your body and let it out","to close your eyes and sleep","to move your arms quickly"],"key":1,"explanation":"In this sentence, the underlined word means \"to take air into your body and let it out\". The other options do not fit the sentence."},{"id":"v5","text":"The driver will <u>deliver</u> our new table today.<p>What does the underlined word or phrase mean?</p>","options":["to take something to the person or place waiting for it","to make something from wood","to hide something under a bed","to throw something into a bin"],"key":0,"explanation":"In this sentence, the underlined word means \"to take something to the person or place waiting for it\". The other options do not fit the sentence."},{"id":"v6","text":"The magic trick was <u>amazing</u>!<p>What does the underlined word or phrase mean?</p>","options":["so heavy that you cannot lift it","so cold that water freezes","so dark that you cannot see","so surprising or good that it makes you say wow"],"key":3,"explanation":"In this sentence, the underlined word means \"so surprising or good that it makes you say wow\". The other options do not fit the sentence."},{"id":"v7","text":"I had a <u>dream</u> about flying while I was asleep.<p>What does the underlined word or phrase mean?</p>","options":["a game you play with a ball","a meal you eat in the morning","pictures or events you see in your mind while sleeping","a noise you hear at the door"],"key":2,"explanation":"In this sentence, the underlined word means \"pictures or events you see in your mind while sleeping\". The other options do not fit the sentence."},{"id":"v8","text":"We saw an orange and white <u>clownfish</u>.<p>What does the underlined word or phrase mean?</p>","options":["a bird with a red head","a small sea fish, often orange with white stripes","a person who makes jokes","a plant that grows in a garden"],"key":1,"explanation":"In this sentence, the underlined word means \"a small sea fish, often orange with white stripes\". The other options do not fit the sentence."},{"id":"v9","text":"Rain is <u>common</u> here in spring.<p>What does the underlined word or phrase mean?</p>","options":["happening often or found in many places","happening only once in many years","being difficult to understand","being very dangerous to touch"],"key":0,"explanation":"In this sentence, the underlined word means \"happening often or found in many places\". The other options do not fit the sentence."},{"id":"v10","text":"Use a <u>sponge</u> to clean the table.<p>What does the underlined word or phrase mean?</p>","options":["a sharp tool for cutting paper","a hard stone used for building","a glass dish for keeping fruit","a soft object with small holes that can hold water"],"key":3,"explanation":"In this sentence, the underlined word means \"a soft object with small holes that can hold water\". The other options do not fit the sentence."},{"id":"v11","text":"The fish moves its <u>fin</u> as it swims.<p>What does the underlined word or phrase mean?</p>","options":["a part of a bird used for flying","a part of a tree under the ground","a part of a fish that helps it move and balance in water","a part of a person used for hearing"],"key":2,"explanation":"In this sentence, the underlined word means \"a part of a fish that helps it move and balance in water\". The other options do not fit the sentence."},{"id":"v12","text":"We want to <u>explore</u> the island and see new places.<p>What does the underlined word or phrase mean?</p>","options":["to leave a place without looking at it","to look around a place and learn about it","to build a wall around a place","to clean every room in a building"],"key":1,"explanation":"In this sentence, the underlined word means \"to look around a place and learn about it\". The other options do not fit the sentence."},{"id":"v13","text":"The <u>scientist</u> studies plants in a laboratory.<p>What does the underlined word or phrase mean?</p>","options":["a person who studies how things in the world work","a person who cooks meals in a cafe","a person who carries letters to homes","a person who sings on a stage"],"key":0,"explanation":"In this sentence, the underlined word means \"a person who studies how things in the world work\". The other options do not fit the sentence."},{"id":"v14","text":"Please do not <u>interrupt</u> me while I am speaking.<p>What does the underlined word or phrase mean?</p>","options":["to listen quietly until someone finishes","to write every word someone says","to smile when someone tells a joke","to stop someone from continuing by speaking or doing something"],"key":3,"explanation":"In this sentence, the underlined word means \"to stop someone from continuing by speaking or doing something\". The other options do not fit the sentence."},{"id":"v15","text":"The car may <u>get stuck</u> in the deep mud.<p>What does the underlined word or phrase mean?</p>","options":["to move much faster than before","to arrive earlier than expected","to be unable to move out of a place","to turn around and drive home"],"key":2,"explanation":"In this sentence, the underlined word means \"to be unable to move out of a place\". The other options do not fit the sentence."},{"id":"v16","text":"The light came on <u>instantly</u> when I pressed the switch.<p>What does the underlined word or phrase mean?</p>","options":["after a very long time","right away, with no waiting","only at the end of the day","again and again each week"],"key":1,"explanation":"In this sentence, the underlined word means \"right away, with no waiting\". The other options do not fit the sentence."},{"id":"v17","text":"The dog may <u>bite</u> if it is frightened.<p>What does the underlined word or phrase mean?</p>","options":["to cut or hold something with the teeth","to touch something with a foot","to look at something with the eyes","to smell something with the nose"],"key":0,"explanation":"In this sentence, the underlined word means \"to cut or hold something with the teeth\". The other options do not fit the sentence."},{"id":"v18","text":"I missed lunch. <u>I am starving</u>!<p>What does the underlined word or phrase mean?</p>","options":["I am very sleepy","I am very cold","I am very angry","I am very hungry"],"key":3,"explanation":"In this sentence, the underlined word means \"I am very hungry\". The other options do not fit the sentence."},{"id":"v19","text":"The <u>diver</u> swims deep under the water.<p>What does the underlined word or phrase mean?</p>","options":["a person who climbs tall trees","a person who drives a train","a person who goes under water to swim or work","a person who flies an airplane"],"key":2,"explanation":"In this sentence, the underlined word means \"a person who goes under water to swim or work\". The other options do not fit the sentence."},{"id":"v20","text":"The rabbit managed to <u>escape</u> from the cage.<p>What does the underlined word or phrase mean?</p>","options":["to go back into a small cage","to get away from a place where you are trapped","to wait quietly for someone","to help another animal find food"],"key":1,"explanation":"In this sentence, the underlined word means \"to get away from a place where you are trapped\". The other options do not fit the sentence."},{"id":"v21","text":"<u>Grab</u> the handle before the door closes.<p>What does the underlined word or phrase mean?</p>","options":["to take or hold something quickly","to look at something from far away","to draw a picture of something","to drop something very slowly"],"key":0,"explanation":"In this sentence, the underlined word means \"to take or hold something quickly\". The other options do not fit the sentence."},{"id":"v22","text":"Please <u>slow down</u> when you ride near people.<p>What does the underlined word or phrase mean?</p>","options":["to move or do something faster","to make something much louder","to put something higher up","to move or do something less quickly"],"key":3,"explanation":"In this sentence, the underlined word means \"to move or do something less quickly\". The other options do not fit the sentence."},{"id":"v23","text":"We watched fish swimming in the <u>aquarium</u>.<p>What does the underlined word or phrase mean?</p>","options":["a place where books are borrowed","a place where airplanes land","a water tank or place where fish and other water animals are kept","a field where vegetables grow"],"key":2,"explanation":"In this sentence, the underlined word means \"a water tank or place where fish and other water animals are kept\". The other options do not fit the sentence."},{"id":"v24","text":"Your shoes are <u>filthy</u> after walking in the mud.<p>What does the underlined word or phrase mean?</p>","options":["completely new","very dirty","very comfortable","brightly coloured"],"key":1,"explanation":"In this sentence, the underlined word means \"very dirty\". The other options do not fit the sentence."},{"id":"v25","text":"The flowers in the garden look <u>pretty</u>.<p>What does the underlined word or phrase mean?</p>","options":["nice to look at","difficult to carry","loud enough to hear","ready to eat"],"key":0,"explanation":"In this sentence, the underlined word means \"nice to look at\". The other options do not fit the sentence."},{"id":"v26","text":"Please <u>rinse</u> the cup with clean water.<p>What does the underlined word or phrase mean?</p>","options":["to break something into pieces","to cover something with paper","to fill something with stones","to wash something with water"],"key":3,"explanation":"In this sentence, the underlined word means \"to wash something with water\". The other options do not fit the sentence."},{"id":"v27","text":"The sky is cloudy, so it will <u>probably</u> rain.<p>What does the underlined word or phrase mean?</p>","options":["never able to happen","already finished yesterday","likely to happen, but not certain","happening very noisily"],"key":2,"explanation":"In this sentence, the underlined word means \"likely to happen, but not certain\". The other options do not fit the sentence."},{"id":"v28","text":"Heavy rain caused a <u>delay</u>, so the bus arrived late.<p>What does the underlined word or phrase mean?</p>","options":["a trip that finishes early","a wait that makes something happen later","a sound that is very loud","a prize for winning a game"],"key":1,"explanation":"In this sentence, the underlined word means \"a wait that makes something happen later\". The other options do not fit the sentence."},{"id":"v29","text":"The <u>lady</u> at the shop helped my mother.<p>What does the underlined word or phrase mean?</p>","options":["a woman","a young boy","a baby animal","a school building"],"key":0,"explanation":"In this sentence, the underlined word means \"a woman\". The other options do not fit the sentence."}]},{"id":"language","title":"Language Form and Meaning","questions":[{"id":"g0","text":"Every afternoon, Ava <strong>_____</strong> her dog.","options":["walk","walks","is walking","walked"],"key":1,"explanation":"This is a habit or routine (every afternoon, every day, usually, every night). Use the present simple: add -s or -es with he, she, it or a singular noun; use the base form with I, you, we, they or a plural noun."},{"id":"g1","text":"Our school bus <strong>_____</strong> at seven every morning.","options":["arrives","arrive","is arriving","arrived"],"key":0,"explanation":"This is a habit or routine (every afternoon, every day, usually, every night). Use the present simple: add -s or -es with he, she, it or a singular noun; use the base form with I, you, we, they or a plural noun."},{"id":"g2","text":"The twins <strong>_____</strong> breakfast together every day.","options":["eats","is eating","ate","eat"],"key":3,"explanation":"This is a habit or routine (every afternoon, every day, usually, every night). Use the present simple: add -s or -es with he, she, it or a singular noun; use the base form with I, you, we, they or a plural noun."},{"id":"g3","text":"My aunt <strong>_____</strong> in a bookshop on weekdays.","options":["work","is working","works","worked"],"key":2,"explanation":"This is a habit or routine (every afternoon, every day, usually, every night). Use the present simple: add -s or -es with he, she, it or a singular noun; use the base form with I, you, we, they or a plural noun."},{"id":"g4","text":"We usually <strong>_____</strong> our shoes by the door.","options":["leaves","leave","is leaving","left"],"key":1,"explanation":"This is a habit or routine (every afternoon, every day, usually, every night). Use the present simple: add -s or -es with he, she, it or a singular noun; use the base form with I, you, we, they or a plural noun."},{"id":"g5","text":"Every night, Dad <strong>_____</strong> a story to us.","options":["reads","read","are reading","reading"],"key":0,"explanation":"This is a habit or routine (every afternoon, every day, usually, every night). Use the present simple: add -s or -es with he, she, it or a singular noun; use the base form with I, you, we, they or a plural noun."},{"id":"g6","text":"Yesterday, Ben <strong>_____</strong> a picture of a fish.","options":["draw","draws","is drawing","drew"],"key":3,"explanation":"The time words (yesterday, last Saturday, last night, two days ago, last month) show a finished past action. Use the past simple."},{"id":"g7","text":"Last Saturday, we <strong>_____</strong> our grandparents.","options":["visit","visits","visited","are visiting"],"key":2,"explanation":"The time words (yesterday, last Saturday, last night, two days ago, last month) show a finished past action. Use the past simple."},{"id":"g8","text":"The cat <strong>_____</strong> under the chair last night.","options":["sleep","slept","sleeps","is sleeping"],"key":1,"explanation":"The time words (yesterday, last Saturday, last night, two days ago, last month) show a finished past action. Use the past simple."},{"id":"g9","text":"Two days ago, Lucy <strong>_____</strong> her lunchbox at home.","options":["forgot","forget","forgets","is forgetting"],"key":0,"explanation":"The time words (yesterday, last Saturday, last night, two days ago, last month) show a finished past action. Use the past simple."},{"id":"g10","text":"Last month, the class <strong>_____</strong> a new song.","options":["learn","learns","is learning","learned"],"key":3,"explanation":"The time words (yesterday, last Saturday, last night, two days ago, last month) show a finished past action. Use the past simple."},{"id":"g11","text":"I <strong>_____</strong> a blue shell on the beach yesterday.","options":["find","finds","found","am finding"],"key":2,"explanation":"The time words (yesterday, last Saturday, last night, two days ago, last month) show a finished past action. Use the past simple."},{"id":"g12","text":"Look! The puppy <strong>_____</strong> after the ball.","options":["run","is running","runs","ran"],"key":1,"explanation":"Look!, Listen!, right now and at the moment show the action is happening now. Use am, is or are plus the -ing form, matching the subject."},{"id":"g13","text":"Right now, the children <strong>_____</strong> paper boats.","options":["are making","make","makes","made"],"key":0,"explanation":"Look!, Listen!, right now and at the moment show the action is happening now. Use am, is or are plus the -ing form, matching the subject."},{"id":"g14","text":"Listen! Our neighbour <strong>_____</strong> the piano now.","options":["play","plays","played","is playing"],"key":3,"explanation":"Look!, Listen!, right now and at the moment show the action is happening now. Use am, is or are plus the -ing form, matching the subject."},{"id":"g15","text":"At this moment, I <strong>_____</strong> a glass of milk.","options":["drink","drinks","am drinking","drank"],"key":2,"explanation":"Look!, Listen!, right now and at the moment show the action is happening now. Use am, is or are plus the -ing form, matching the subject."},{"id":"g16","text":"Be quiet! The baby <strong>_____</strong> right now.","options":["sleep","is sleeping","slept","are sleeping"],"key":1,"explanation":"Look!, Listen!, right now and at the moment show the action is happening now. Use am, is or are plus the -ing form, matching the subject."},{"id":"g17","text":"The boys <strong>_____</strong> the classroom at the moment.","options":["are cleaning","clean","cleans","cleaned"],"key":0,"explanation":"Look!, Listen!, right now and at the moment show the action is happening now. Use am, is or are plus the -ing form, matching the subject."},{"id":"g18","text":"At four yesterday afternoon, I <strong>_____</strong> in the garden.","options":["were playing","am playing","play","was playing"],"key":3,"explanation":"The action was in progress at a past time or when something else happened. Use was (I, he, she, it) or were (you, we, they) plus the -ing form."},{"id":"g19","text":"At eight last night, the girls <strong>_____</strong> a film.","options":["was watching","are watching","were watching","watch"],"key":2,"explanation":"The action was in progress at a past time or when something else happened. Use was (I, he, she, it) or were (you, we, they) plus the -ing form."},{"id":"g20","text":"Dad <strong>_____</strong> dinner when I called him yesterday.","options":["were cooking","was cooking","is cooking","cooks"],"key":1,"explanation":"The action was in progress at a past time or when something else happened. Use was (I, he, she, it) or were (you, we, they) plus the -ing form."},{"id":"g21","text":"We <strong>_____</strong> home when the rain began yesterday.","options":["were walking","was walking","are walking","walk"],"key":0,"explanation":"The action was in progress at a past time or when something else happened. Use was (I, he, she, it) or were (you, we, they) plus the -ing form."},{"id":"g22","text":"Ella <strong>_____</strong> her room when her friend arrived yesterday.","options":["were tidying","is tidying","tidies","was tidying"],"key":3,"explanation":"The action was in progress at a past time or when something else happened. Use was (I, he, she, it) or were (you, we, they) plus the -ing form."},{"id":"g23","text":"The birds <strong>_____</strong> above the lake when we saw them yesterday.","options":["was flying","are flying","were flying","fly"],"key":2,"explanation":"The action was in progress at a past time or when something else happened. Use was (I, he, she, it) or were (you, we, they) plus the -ing form."},{"id":"g24","text":"I <strong>_____</strong> that story three times so far.","options":["has read","have read","am reading","reads"],"key":1,"explanation":"So far, already, since and twice connect the past to now. Use have (I, you, we, they) or has (he, she, it) plus the past participle."},{"id":"g25","text":"She <strong>_____</strong> her bag, so she cannot find her books now.","options":["has lost","have lost","is losing","loses"],"key":0,"explanation":"So far, already, since and twice connect the past to now. Use have (I, you, we, they) or has (he, she, it) plus the past participle."},{"id":"g26","text":"We <strong>_____</strong> two songs so far today.","options":["has sung","are singing","sing","have sung"],"key":3,"explanation":"So far, already, since and twice connect the past to now. Use have (I, you, we, they) or has (he, she, it) plus the past participle."},{"id":"g27","text":"Leo <strong>_____</strong> his hands already.","options":["have washed","is washing","has washed","washes"],"key":2,"explanation":"So far, already, since and twice connect the past to now. Use have (I, you, we, they) or has (he, she, it) plus the past participle."},{"id":"g28","text":"They <strong>_____</strong> in this house since 2020.","options":["has lived","have lived","live","are living"],"key":1,"explanation":"So far, already, since and twice connect the past to now. Use have (I, you, we, they) or has (he, she, it) plus the past participle."},{"id":"g29","text":"Mum <strong>_____</strong> that museum twice.","options":["has visited","have visited","is visiting","visiting"],"key":0,"explanation":"So far, already, since and twice connect the past to now. Use have (I, you, we, they) or has (he, she, it) plus the past participle."},{"id":"g30","text":"By the time we reached the stop, the bus <strong>_____</strong>.","options":["has left","leaves","is leaving","had left"],"key":3,"explanation":"This action finished before another past event (by the time, before). Use had plus the past participle."},{"id":"g31","text":"Lily <strong>_____</strong> her lunch before the lesson began yesterday.","options":["has eaten","eats","had eaten","is eating"],"key":2,"explanation":"This action finished before another past event (by the time, before). Use had plus the past participle."},{"id":"g32","text":"The ground was wet because it <strong>_____</strong> during the night.","options":["has rained","had rained","rains","is raining"],"key":1,"explanation":"This action finished before another past event (by the time, before). Use had plus the past participle."},{"id":"g33","text":"Before I arrived yesterday, Noah <strong>_____</strong> all the chairs.","options":["had moved","has moved","moves","is moving"],"key":0,"explanation":"This action finished before another past event (by the time, before). Use had plus the past participle."},{"id":"g34","text":"By the time the party started, we <strong>_____</strong> the room.","options":["have decorated","decorate","are decorating","had decorated"],"key":3,"explanation":"This action finished before another past event (by the time, before). Use had plus the past participle."},{"id":"g35","text":"She <strong>_____</strong> the book before she lent it to me last week.","options":["has finished","finishes","had finished","is finishing"],"key":2,"explanation":"This action finished before another past event (by the time, before). Use had plus the past participle."},{"id":"g36","text":"Every Tuesday, our teacher <strong>_____</strong> us a new game.","options":["show","shows","is showing","showed"],"key":1,"explanation":"Every Tuesday is a routine and our teacher is singular, so use shows."},{"id":"g37","text":"Last night, I <strong>_____</strong> a letter to my cousin.","options":["wrote","write","writes","am writing"],"key":0,"explanation":"Last night is finished past time, so use the past simple wrote."}]}],"tasks":[{"id":"writing-story","section":"writing","title":"Picture Story","answerId":"writing-story1","rubric":"writing","prompt":"Look at the four pictures in order and write a story of about 6-8 sentences: who is in the story, what happens, and how it ends. Characters: Maya (the girl), Sam (the boy), Maya''s mother, and a puppy. The pictures show: (1) Maya walking along a village street finds a small, muddy brown puppy sitting alone under a big tree; (2) at home Maya dries the puppy with a blue towel, with a water bowl and dog bed nearby; (3) Maya and her mother pin a \"found puppy\" poster with the puppy''s picture on a notice board while Sam points at it; (4) at Sam''s front door, Sam happily hugs the puppy, which is his lost dog, while Maya and her mother smile. Accept reasonable details consistent with the pictures."},{"id":"writing-sentences","section":"writing","title":"Make Sentences with Linking Words","rubric":"sentences","answerIds":[{"word":"both","answerId":"writing-link0"},{"word":"similarly","answerId":"writing-link1"},{"word":"also","answerId":"writing-link2"},{"word":"in the same way","answerId":"writing-link3"},{"word":"however","answerId":"writing-link4"},{"word":"on the other hand","answerId":"writing-link5"},{"word":"in contrast","answerId":"writing-link6"},{"word":"while","answerId":"writing-link7"},{"word":"whereas","answerId":"writing-link8"},{"word":"overall","answerId":"writing-link9"}],"prompt":"Write one complete sentence for each linking word or expression, using it correctly for its meaning (addition, similarity, contrast, summary). Do not copy the example \"I enjoy drawing, and I also enjoy reading.\""},{"id":"speaking-1","section":"speaking","title":"Read Aloud","rubric":"readAloud","prompt":"Read the passage aloud clearly.","target":"The School GardenLily and Ben visit their school garden on Friday. The sun is warm, and the flowers are bright. Lily gives water to a young bean plant. Ben sees a yellow butterfly near a flower. He points to it and smiles. The children enjoy looking after the garden. They hope the plants will grow tall and strong. Before they leave, they pull out some weeds and collect their tools. Their teacher thanks them for helping. Next week, they will return to check the beans and draw pictures of the flowers. Gardening makes their school a beautiful place for everyone to enjoy."},{"id":"speaking-2","section":"speaking","title":"Tell a Picture Story","rubric":"speaking","prompt":"Tell the six-picture story using first, next, then, finally. Characters: Mia (yellow shirt), Leo (green shirt), and a park keeper (blue clothes). The pictures show: (1) Mia and Leo walk through a park by a lake carrying a red kite; (2) Leo flies the kite while Mia watches happily; (3) the kite gets stuck high in a tree and the children look worried; (4) they ask a park keeper for help, pointing at the tree; (5) the park keeper uses a long pole to free the kite; (6) Mia holds the kite and Leo shakes the park keeper''s hand to thank him. Accept reasonable details consistent with the pictures."},{"id":"speaking-3","section":"speaking","title":"Watch and Retell","rubric":"speaking","prompt":"Retell the short video \"Little Fish''s Ocean Friends\": who you saw, what happened, and how it ended. In the video Little Fish swims through the ocean saying good morning to Starfish, meets Crab (\"click click\"), then Baby Turtle, who says he is very slow; the friends help and wait for him and he thanks them. They play games among the seaweed and with bubbles from clams, meet a shy Seahorse (\"Hello there, don''t be shy\"), and play together all day; it was a perfect day in the ocean. Accept reasonable retellings of these events."}]}'::jsonb) on conflict(exam_id) do update set version=excluded.version,content=excluded.content;
